const raw = $json.text ?? $json.response ?? $json.output ?? JSON.stringify($json);
let result; try { result = JSON.parse(raw); } catch { throw new Error("Grouper returned invalid JSON"); }
if (!Array.isArray(result.groups) || !Array.isArray(result.unselected_article_ids)) throw new Error("Invalid grouping contract");
const candidates = $node["Preparar prompt de agrupación"].json.candidates;
const byId = new Map(candidates.map((item) => [String(item.article_id), item]));
const used = new Set();
const allIds = new Set(candidates.map((item) => String(item.article_id)));
for (const group of result.groups) { if (!Array.isArray(group.ordered_article_ids) || group.ordered_article_ids.length < 2 || group.ordered_article_ids.length > 3) throw new Error("Each group needs 2–3 articles"); for (const id of group.ordered_article_ids) { const key = String(id); if (!byId.has(key) || used.has(key)) throw new Error("Invalid or repeated article ID"); used.add(key); } if (!Number.isInteger(group.target_duration_seconds) || group.target_duration_seconds < 60 || group.target_duration_seconds > 120) throw new Error("Invalid duration"); }
for (const id of result.unselected_article_ids) { const key = String(id); if (!allIds.has(key) || used.has(key)) throw new Error("Invalid unselected article ID"); used.add(key); }
if (used.size !== allIds.size) throw new Error("Every candidate must be selected or unselected");
const day = new Date().toISOString().slice(0, 10);
return result.groups.map((group) => { const members = group.ordered_article_ids.map((id) => byId.get(String(id))); return { json: { queue_key: `daily-news-${day}-${group.ordered_article_ids.join("-")}`, title: `Daily Gaming News — ${day}`, topic: "Gaming News", editorial_angle: group.editorial_angle, selection_reason: group.selection_reason, target_duration_seconds: group.target_duration_seconds, members } }; });
